"1 если сработал детектор магнитных аномалий":"1 se o detector de anomalias magnéticas disparou",
"\n=== ЗАДАЧА ДЛЯ НЕЙРОСЕТИ ===\nПроанализируй телеметрию датчиков DeviceOrientation, Gyroscope и вычисленного курса (PDR / Comp) при ходьбе/наклонах устройства.\nПроблема: в некоторых направлениях компас и конус направления ведут себя стабильно, а при наклоне телефона вперед-назад (угол beta) или при смене направления на перпендикулярное — курс начинает сильно лихорадить и скакать.\n\nОпредели:\n1. Связан ли скачок курса со сменой знака или проекции угла наклона beta/gamma на горизонтальную плоскость?\n2. Есть ли несоответствие между фактической угловой скоростью рыскания (rot[2] / yawRate) и поворотом кватерниона/компаса при наклонах?\n3. Какая математическая ошибка в фильтре ориентации или тригонометрии приводит к этим колебаниям и как её исправить в коде?\n\n=== ТЕЛЕМЕТРИЯ (JSON) ===\n{0}\n":"\n=== TAREFA PARA A REDE NEURAL ===\nAnalise a telemetria dos sensores DeviceOrientation e Gyroscope e do rumo calculado (PDR / Comp) durante a caminhada/inclinação do aparelho.\nProblema: em algumas direções a bússola e o cone de direção se comportam de forma estável, mas ao inclinar o telefone para frente/trás (ângulo beta) ou ao mudar para uma direção perpendicular, o rumo começa a oscilar e a dar saltos bruscos.\n\nDetermine:\n1. O salto no rumo está relacionado a uma troca de sinal ou à projeção do ângulo de inclinação beta/gamma no plano horizontal?\n2. Há divergência entre a velocidade angular real de guinada (rot[2] / yawRate) e a rotação do quatérnion/bússola durante as inclinações?\n3. Qual erro matemático no filtro de orientação ou na trigonometria causa essas oscilações e como corrigi-lo no código?\n\n=== TELEMETRIA (JSON) ===\n{0}\n",
