"Грибы жмутся к нижней части склонов и к карманам мелкозёма. На гребнях слой появляется только после затяжных дождей.":"Os cogumelos se concentram na parte baixa das encostas e nos bolsões de terra fina. Nos cumes, a camada só aparece após chuvas prolongadas.",
"Сосняк сфагновый / Заболоченный сосновый лес":"Pinhal com esfagno / Pinhal encharcado",
"Торфяно-подзолисто-глеевая / Торфянисто-глеевая":"Turfoso-podzólico-glei / Turfoso-glei",
"Переходная зона между сухим бором и верховым болотом: сосна растёт на кочках, подстилка — сфагново-кустарничковая, уровень грунтовых вод держится в 20–40 см от поверхности.":"Zona de transição entre o pinhal seco e a turfeira alta: o pinheiro cresce em montículos, a serapilheira é de esfagno e subarbustos, e o lençol freático fica a 20–40 cm da superfície.",
"Сосна обыкновенная (болотная форма)":"Pinheiro-silvestre (forma de turfeira)",
