"Черника (на кочках)":"Mirtilo (em montículos)",
"Строчок обыкновенный (на сухих гривах)":"Falsa-morela (em cristas secas)",
"Моховик зелёный":"Boleto-verde",
"Маслёнок болотный (Suillus flavidus)":"Boleto de turfeira (Suillus flavidus)",
"Польский гриб (на гривах)":"Boleto-baio (em cristas)",
"Горькушка":"Lactário amargo",
"Грибы — на сухих гривах и кочках у основания сосен, ягоды (клюква, голубика) — в мочажинах. Идите по краю, не выходя на открытый сфагновый ковёр.":"Os cogumelos crescem em cristas secas e montículos na base dos pinheiros; os frutos silvestres (oxicoco, mirtilo) ficam nas depressões úmidas. Siga pela borda e não pise no tapete aberto de esfagno.",
"Торфяная выработка / Карты и обводнённые торфяные карьеры":"Área de extração de turfa / Talhões e cavas de turfa alagadas",
"Торфяная остаточная / Постпирогенная органогенная":"Turfa residual / Organogênico pós-incêndio",
"Бывшие торфоразработки: прямоугольные карты, канавы и валы, местами обводнённые, местами сухие. Верхний слой торфа снят или перемешан, поэтому почва молодая, неоднородная, зарастает берёзой, ивой, иван-чаем и тростником.":"Antigas áreas de extração de turfa: talhões retangulares, valas e taludes, ora alagados, ora secos. A camada superior de turfa foi retirada ou misturada, então o solo é jovem, heterogêneo e coberto por bétula, salgueiro, epilóbio e juncos.",
"Берёза повислая и пушистая (самосев)":"Bétula-pendente e bétula-pubescente (regeneração natural)",
"Ива козья / пепельная":"Salgueiro-caprino / salgueiro-cinzento",
"Сосна (подрост на валах)":"Pinheiro (regeneração nos taludes)",
"Иван-чай":"Epilóbio",
"Тростник":"Caniço",
"Хвощ":"Cavalinha",
"Подорожник":"Tanchagem",
"Сабельник":"Potentilla palustris",
"Ситник":"Junco",
"Строчок (на сухих валах)":"Falsa-morela (em taludes secos)",
"Сморчковая шапочка по гарям":"Morela-sino em áreas queimadas",
"Подберёзовик обыкновенный (под молодой берёзой)":"Boleto-de-bétula comum (sob bétulas jovens)",
"Сыроежки":"Russulas",
"Подберёзовики":"Boletos-de-bétula",
"Подосиновик (под осиной)":"Boleto-laranja (sob choupo-tremedor)",
"Козляк":"Boleto-cabra",
"Моховик":"Boleto-marrom",
"Опёнок осенний (на пнях)":"Armillaria (em tocos)",
"Грибы идут по валам и бровкам между картами, под молодой берёзой и осиной. Осторожно: обводнённые карты глубокие, берега торфа обрываются, а выработки склонны к торфяным пожарам.":"Os cogumelos crescem nos taludes e bordas entre os talhões, sob bétulas e choupos jovens. Cuidado: os talhões alagados são fundos, as margens de turfa desmoronam e as áreas de extração são propensas a incêndios de turfa.",
"Песчаный карьер / Пионерные заросли на песках":"Areal / Vegetação pioneira sobre areias",
"Псаммозём первичный / Карьерно-отвальный (молодая почва)":"Psamossolo primário / Solo de aterro de pedreira (solo jovem)",
"Вскрытый или недавно рекультивированный песок. Гумусового горизонта почти нет, вода уходит мгновенно. На отвалах — пионерная растительность, молодые сосновые посадки и берёзовый самосев, по днищу карьера обычно есть обводнённые понижения.":"Areia exposta ou recentemente recuperada. Quase não há horizonte húmico e a água escoa na hora. Nos montes de rejeito há vegetação pioneira, plantios jovens de pinheiro e regeneração de bétula; no fundo do areal costuma haver depressões alagadas.",
"Сосна обыкновенная (посадки, самосев)":"Pinheiro-silvestre (plantios, regeneração natural)",
"Ива":"Salgueiro",
"Осина (по краям)":"Choupo-tremedor (nas bordas)",
"Тимофеевка степная":"Phleum phleoides",
"Пижма":"Tanaceto",
"Козлятник":"Galega",
"Ястребинка":"Hieracium",
"Лишайники Cladonia":"Líquens Cladonia",
"Строчок (под молодыми соснами)":"Falsa-morela (sob pinheiros jovens)",
"Маслёнок поздний (под молодой сосной)":"Suillus luteus (sob pinheiro jovem)",
"Болетус зернистый":"Boleto granulado",
"Рядовка серая и жёлто-бурая":"Tricholoma cinzento e amarelo-acastanhado",
"Грибы — только под посадками сосны старше 8–10 лет, у стенок карьера и вдоль дорог. На голом песке плодоношения нет. Берегитесь осыпающихся откосов и глубоких обводнённых карьеров.":"Cogumelos apenas sob plantios de pinheiro com mais de 8–10 anos, junto às paredes do areal e ao longo de estradas. Não há frutificação em areia nua. Cuidado com taludes que desmoronam e areais profundos alagados.",
