"Северный склон (С)":"Encosta voltada ao norte (N)",
"Меньше всего солнца. Весной прогревается позже, но летом сохраняет прохладу и влагу.":"Recebe menos sol. Esquenta mais tarde na primavera, mas mantém frescor e umidade no verão.",
"Северо-восточный склон (СВ)":"Encosta voltada ao nordeste (NE)",
"Мягкое утреннее солнце, устойчивая влажность.":"Sol suave da manhã, umidade estável.",
"Восточный склон (В)":"Encosta voltada ao leste (L)",
"Прогрев первыми лучами, раннее испарение росы.":"Aquece com os primeiros raios; o orvalho evapora cedo.",
"Юго-восточный склон (ЮВ)":"Encosta voltada ao sudeste (SE)",
"Хорошо прогреваемый склон. Весенний старт на 5–7 дней раньше.":"Encosta bem aquecida. O início da primavera é 5–7 dias mais cedo.",
"Южный склон (Ю)":"Encosta voltada ao sul (S)",
"Максимум инсоляции. Весной оттаивает на 10–14 дней раньше (первые сморчки), в засуху быстро пересыхает.":"Máxima insolação. Descongela 10–14 dias antes na primavera (primeiras morelas) e resseca rápido na seca.",
"Юго-западный склон (ЮЗ)":"Encosta voltada ao sudoeste (SO)",
"Очень тёплый склон вечернего солнца, быстрый сход снега.":"Encosta muito quente, com sol da tarde e degelo rápido.",
"Западный склон (З)":"Encosta voltada ao oeste (O)",
"Наветренная сторона для атлантических циклонов, умеренно тёплый.":"Lado de barlavento para os ciclones atlânticos; moderadamente quente.",
"Северо-западный склон (СЗ)":"Encosta voltada ao noroeste (NO)",
