"Сыпучая почва, мгновенный дренаж, влагу почти не держит.":"Solo solto, drenagem instantânea, quase não retém umidade.",
"Супесь (Loamy sand)":"Areia franca (Loamy sand)",
"Отличная аэрация и дренаж; оптимум для сосновых боров.":"Excelente aeração e drenagem; ideal para pinhais.",
"Лёгкий суглинок (Sandy loam)":"Franco-arenoso (Sandy loam)",
"Тёплая, быстро прогреваемая почва с умеренной влагоёмкостью.":"Solo quente, que aquece rápido, com capacidade moderada de retenção de água.",
"Суглинок (Loam)":"Franco (Loam)",
"Идеальный баланс песка, ила и глины для лесной растительности.":"Equilíbrio ideal de areia, silte e argila para a vegetação florestal.",
"Пылеватый суглинок (Silt loam)":"Franco-siltoso (Silt loam)",
"Мягкая, влагоёмкая, легко заплывает и размывается.":"Macio, retém umidade, assoreia e erode com facilidade.",
"Пылеватая почва (Silt)":"Solo siltoso (Silt)",
"Очень мягкая, легко размываемая почва речных долин.":"Solo muito macio de vales fluviais, facilmente erodido.",
"Песчанистый тяжёлый суглинок":"Franco-argilo-arenoso",
"Сбалансированная почва со стабильным водным режимом.":"Solo equilibrado, com regime hídrico estável.",
"Тяжёлый суглинок (Clay loam)":"Franco-argiloso (Clay loam)",
"Влагоёмкая и богатая минералами, но медленно дренируется.":"Retém umidade e é rico em minerais, mas drena devagar.",
"Пылеватый тяжёлый суглинок":"Franco-argilo-siltoso",
"Влагоёмкая пойменная почва.":"Solo de várzea que retém umidade.",
"Песчанистая глина (Sandy clay)":"Argila arenosa (Sandy clay)",
"Плотная, но с песчаной фракцией.":"Denso, mas com fração arenosa.",
"Пылеватая глина (Silty clay)":"Argila siltosa (Silty clay)",
"Холодная, вязкая и липкая.":"Fria, viscosa e pegajosa.",
"Тяжёлая глина (Clay)":"Argila pesada (Clay)",
"Плотная, холодная, задерживает воду, трескается при высыхании.":"Densa, fria, retém água e racha ao secar.",
"Смешанный суглинок":"Franco misto",
"Умеренно лёгкий механический состав с хорошей аэрацией.":"Textura moderadamente leve, com boa aeração.",
"Экстремально кислая":"Extremamente ácido",
"Угнетает большинство деревьев, кроме сосны и берёзы. Рай для сфагнума, вереска и черники.":"Inibe a maioria das árvores, exceto pinheiro e bétula. Paraíso do esfagno, da urze e do mirtilo.",
"Сильнокислая":"Fortemente ácido",
"Оптимум для хвойников, боровиков, польских грибов и брусники.":"Ideal para coníferas, boletos-rei, boletos-baios e arando-vermelho.",
"Слабокислая":"Levemente ácido",
"Типична для смешанных лесов, ельников, черничников и подосиновиков.":"Típico de florestas mistas, florestas de abeto, mirtilais e boletos-laranja.",
"Нейтральная":"Neutro",
"Идеал для широколиственных дубрав, сморчков, зонтиков и богатого подлеска.":"Ideal para carvalhais de folhosas, morelas, cogumelos-guarda-chuva e sub-bosque rico.",
"Слабощелочная":"Levemente alcalino",
"Карбонатная почва. Любима орхидеями, ясенем и шампиньонами.":"Solo carbonático. Apreciado por orquídeas, freixos e champignons.",
"Сильнощелочная":"Fortemente alcalino",
"Избыток свободной извести или солей.":"Excesso de cal livre ou sais.",
