"Быстрая минерализация, много азота: нитрофилы (крапива, малина), шампиньоны и дождевики.":"Mineralização rápida, muito nitrogênio: nitrófilas (urtiga, framboesa), champignons e bufas-de-lobo.",
"узкое (мягкий гумус, mull)":"estreita (húmus suave, mull)",
"Плодородный быстро разлагаемый опад: дубравы, зонтики, сморчки.":"Serapilheira fértil e de decomposição rápida: carvalhais, cogumelos-guarda-chuva, morelas.",
"среднее (moder)":"média (moder)",
"Типичный лесной гумус: смешанные и хвойные леса, большая часть съедобной микоризы.":"Húmus florestal típico: florestas mistas e de coníferas, a maior parte dos cogumelos micorrízicos comestíveis.",
"широкое (сырой гумус, mor)":"ampla (húmus bruto, mor)",
"Кислый грубый гумус: вереск, брусника, сфагнум; микоризные грибы доминируют над сапротрофами.":"Húmus grosseiro ácido: urze, arando-vermelho, esfagno; fungos micorrízicos dominam sobre os sapróbios.",
"Низкий (олиготрофный)":"Baixo (oligotrófico)",
"Средний (мезотрофный)":"Médio (mesotrófico)",
"Высокий (эутрофный)":"Alto (eutrófico)",
