"Средняя: хороший запас обменного Ca, K и Mg.":"Médio: boa reserva de Ca, K e Mg trocáveis.",
"Высокая: глинистые или гумусные почвы с большой поглотительной способностью.":"Alto: solos argilosos ou húmicos com grande capacidade de absorção.",
