"Почва слишком холодная: плодоношение практически остановлено до потепления.":"O solo está frio demais: a frutificação está praticamente parada até esquentar.",
"Влаги мало: нужно ≥ 20–25 мм за 10 дней, после этого первые плодовые тела через 6–12 дней.":"Pouca umidade: são necessários ≥ 20–25 mm em 10 dias; depois disso, os primeiros corpos de frutificação surgem em 6–12 dias.",
"Недавний значимый дождь ({0} дн. назад): основная волна ожидается через ~{1}–{2} дн.":"Chuva significativa recente (há {0} d): a principal onda é esperada em ~{1}–{2} d.",
"Окно максимума: 4–12 дней после основного дождя — самое время идти.":"Janela de pico: 4–12 dias após a chuva principal — a melhor hora de ir.",
"Влага накоплена, но свежих ливней нет: слой доживает, ищите в тенистых и влажных местах.":"A umidade está acumulada, mas não há chuvas fortes recentes: a onda está no fim, procure em locais sombreados e úmidos.",
"Условия переменные: ориентируйтесь на ближайшие осадки и ночные температуры.":"Condições variáveis: oriente-se pela chuva prevista e pelas temperaturas noturnas.",
" Прогноз: ещё {0} мм в ближайшие 2 суток, что поддержит слой.":" Previsão: mais {0} mm nos próximos 2 dias, o que vai sustentar a onda.",
