"Температура почвы около 0 °C. Мицелий шляпочных грибов в покое.":"A temperatura do solo está em torno de 0 °C. O micélio dos cogumelos de chapéu está em repouso.",
"Заморозки прервали плодоношение":"A geada interrompeu a frutificação",
