"Дефицит влаги тормозит развитие плодовых тел.":"A falta de umidade retarda o desenvolvimento dos corpos de frutificação.",
"⚡ Импульс после термошока":"⚡ Impulso após choque térmico",
"Резкий перепад температур после обильного дождя. Классический пусковой триггер выхода белых, подосиновиков и рыжиков.":"Variação brusca de temperatura após chuva forte. Gatilho clássico para a saída de boletos-rei, boletos-laranja e lactários.",
"🔥 Мощный оптимум слоя":"🔥 Ótimo intenso da onda",
"Идеальный баланс тепла и влаги в бору: слой боровиков и маслят в разгаре.":"Equilíbrio ideal de calor e umidade no pinhal: a onda de boletos-rei e suilos está a pleno vapor.",
"Тёплая влажная почва, активный рост белых, подосиновиков и груздей.":"Solo quente e úmido, crescimento ativo de boletos-rei, boletos-laranja e lactários.",
