"Метеоданных нет: ориентируйтесь на тип биотопа и рельеф.":"Sem dados meteorológicos: oriente-se pelo tipo de biótopo e pelo relevo.",
"В ближайшие дни массового плодоношения не ждите: ищите только зимующие виды на валежнике.":"Não espere frutificação em massa nos próximos dias: procure apenas espécies de inverno em madeira morta.",
"ищите в понижениях, у окраин болот, в тени северных склонов и под густым хвойным подростом":"procure em depressões, nas bordas de turfeiras, na sombra de encostas voltadas ao norte e sob regeneração densa de coníferas",
"ближайшее понижение — на {0} (~{1} м)":"a depressão mais próxima fica a {0} (~{1} m)",
"смотрите на повышениях, опушках, гривах и склонах южной экспозиции":"procure em terrenos elevados, bordas de floresta, cristas e encostas voltadas ao sul",
"избегайте глинистых колей и низин":"evite valas argilosas e baixadas",
"оптимальны переходные зоны: склоны, опушки, края вырубок и просек с мхом":"as zonas de transição são ideais: encostas, bordas, margens de clareiras e aceiros com musgo",
"в холодную погоду лучше прогреваемые южные и юго-восточные склоны и песчаные гривы":"no frio, são melhores as encostas voltadas ao sul e sudeste, bem aquecidas, e as cristas arenosas",
