"🍃 Мягкий авторежим: если GPS виден на экране, камера возвращается через 5 секунд после сдвига. Если сместились далеко — остаётся свободной.":"🍃 Modo automático suave: se o GPS estiver visível na tela, a câmera volta 5 segundos após o deslocamento. Se você se afastou muito, ela permanece livre.",
"🔒 Всегда привязана: камера намертво зафиксирована на позиции GPS и блокирует ручное смещение карты.":"🔒 Sempre fixa: a câmera fica firmemente presa à posição do GPS e bloqueia o deslocamento manual do mapa.",
"🔓 Свободная: камера никогда не смещается сама, вы управляете картой полностью вручную.":"🔓 Livre: a câmera nunca se move sozinha; você controla o mapa totalmente à mão.",
