"🧭 Как работает автономное ведение":"🧭 Como funciona a navegação autônoma",
"При подавлении спутников трек строится по шагам и датчикам телефона. Периодически калибруйте компас в воздухе <b>«восьмёркой» (знаком ∞)</b> либо через юстировку компаса ниже, а при выходе к заметным ориентирам уточняйте позицию кнопкой <b>«🧲 Я тут»</b> или через калибировку по трём точкам. В целом навигация в этом режиме осуществляется по принципу определения направления устройства и детекции шагов, так что вам нужно подстроить обе эти составляющие для своего устройства и типа передвижения настройками ниже":"Quando os satélites são bloqueados, a trilha é construída a partir dos passos e dos sensores do telefone. Calibre a bússola periodicamente no ar com um <b>oito (o sinal ∞)</b> ou pelo ajuste da bússola abaixo e, ao chegar a pontos de referência visíveis, refine sua posição com o botão <b>\"🧲 Estou aqui\"</b> ou pela calibração de três pontos. Em geral, a navegação neste modo funciona determinando a direção do aparelho e detectando os passos, então é preciso ajustar esses dois componentes ao seu aparelho e ao seu tipo de deslocamento nas configurações abaixo",
"🚀 Режим движения:":"🚀 Modo de movimento:",
"Автоматически подстраивает длину шага, фильтры тряски и логику ведения курса.":"Ajusta automaticamente o comprimento do passo, os filtros de tremor e a lógica de manutenção do rumo.",
"Обычный шаг":"Passo normal",
"Широкий шаг":"Passada larga",
"Спидометр":"Velocímetro",
"Транспорт":"Veículo",
"Без пешеходных шагов":"Sem passos de caminhada",
"📐 Калибровка по 3 точкам (Макс. точность)":"📐 Calibração de três pontos (Máx. precisão)",
"Запустить мастер":"Iniciar o assistente",
"Вы выберете 3 ориентира на карте (углы домов, перекрёстки) и пройдёте по маршруту <b>A → B → C → A</b>. Алгоритм автоматически рассчитает вашу индивидуальную длину шага и устранит увод компаса вбок.":"Você escolherá 3 pontos de referência no mapa (esquinas de prédios, cruzamentos) e percorrerá a rota <b>A → B → C → A</b>. O algoritmo calculará automaticamente o comprimento individual do seu passo e eliminará o desvio lateral da bússola.",
"🧭 Быстрая юстировка компаса":"🧭 Ajuste rápido da bússola",
"Настроить":"Configurar",
"Быстрое выставление курса телефона по известному ориентиру (Север, Солнце, Луна) без шагов и калибровочных «восьмёрок». Доступно также по <b>долгому нажатию</b> на стрелку компаса 🧭 на карте.":"Defina rapidamente o rumo do telefone por um ponto de referência conhecido (Norte, Sol, Lua), sem passos nem oitos de calibração. Também disponível com um <b>toque longo</b> na seta da bússola 🧭 no mapa.",
"🛡️ Автоматика и экран":"🛡️ Automação e tela",
"Фильтр спуфинга и глушения GPS":"Filtro contra falsificação e bloqueio de GPS",
"Отсекает внезапные скачки в аэропорты, прыжки высоты и скорость >180 км/ч.":"Elimina saltos repentinos para aeroportos, saltos de altitude e velocidades >180 km/h.",
"Авто-старт шагомера при потере GPS":"Iniciar o pedômetro automaticamente ao perder o GPS",
"Плавно продолжает вести трек по датчикам, как только пропадает сигнал со спутников.":"Continua o rastreamento pelos sensores de forma suave assim que o sinal dos satélites some.",
"Кнопка «Поместить GPS сюда (🧲)» на карте":"Botão \"Colocar GPS aqui (🧲)\" no mapa",
"Плавающая кнопка на экране для мгновенной привязки точки к перекрестию. По долгому нажатию доступны быстрые настройки режима без GPS":"Um botão flutuante na tela para fixar o ponto na mira instantaneamente. Um toque longo dá acesso rápido às configurações do modo sem GPS",
"👣 Плашка шагов PDR внизу экрана":"👣 Indicador de passos PDR na parte inferior da tela",
"Отображает компактный счётчик шагов и пройденной дистанции при активном шагомере.":"Mostra um contador compacto de passos e da distância percorrida enquanto o pedômetro está ativo.",
