"Обычный просмотр карты, фильтры и радар видов работают <b>полностью без токена</b>. Ключ необходим только для распознавания видов по фото нейросетью. Токен генерируется в вашем аккаунте на сайте <a href=\"https://www.inaturalist.org/users/api_token\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"link-colored\">inaturalist.org/users/api_token ↗</a>.":"A visualização normal do mapa, os filtros e o radar de espécies funcionam <b>totalmente sem token</b>. A chave só é necessária para reconhecer espécies por foto com a rede neural. O token é gerado na sua conta no site <a href=\"https://www.inaturalist.org/users/api_token\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"link-colored\">inaturalist.org/users/api_token ↗</a>.",
