"Фильтрует аномальные прыжки координат, бег по кругу на 100 км/ч (аэропортовый спуфинг) и удерживает позицию.":"Filtra saltos anômalos de coordenadas e movimentos circulares a 100 km/h (falsificação de aeroportos) e mantém a posição.",
