"Кнопка <b>«Установить на телефон»</b> добавляет приложение на домашний экран прямо из браузера — оно будет работать в полноэкранном режиме и без интернета.":"O botão <b>\"Instalar no celular\"</b> adiciona o aplicativo à tela inicial direto do navegador — ele funcionará em tela cheia e sem internet.",
"📖 Инструкция: получение ключей":"📖 Instruções: como obter chaves",
"<b>Перейдите по ссылке</b>: откройте <a href=\"https://wikimapia.org/api/?action=my_keys\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"link-colored\">wikimapia.org/api/?action=my_keys ↗</a> и авторизуйтесь (или зарегистрируйтесь на Wikimapia).":"<b>Acesse o link</b>: abra <a href=\"https://wikimapia.org/api/?action=my_keys\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"link-colored\">wikimapia.org/api/?action=my_keys ↗</a> e faça login (ou cadastre-se na Wikimapia).",
"<b>Генерация</b>: в нижней части страницы нажмите кнопку <code>Create new key</code>.":"<b>Gere</b>: na parte inferior da página, toque no botão <code>Create new key</code>.",
"<b>Согласие</b>: поставьте галочку <code>I have read Wikimapia Terms of Service</code>.":"<b>Aceite</b>: marque a caixa <code>I have read Wikimapia Terms of Service</code>.",
"<b>Сайт</b>: в поле <i>site</i> вбейте любой произвольный текст или адрес (например, <code>myapp</code>, <code>test</code> или <code>localhost</code>).":"<b>Site</b>: no campo <i>site</i>, digite qualquer texto ou endereço (por exemplo, <code>myapp</code>, <code>test</code> ou <code>localhost</code>).",
"<b>Завершение</b>: нажмите кнопку <code>I accept, Create API KEY</code>.":"<b>Conclua</b>: toque no botão <code>I accept, Create API KEY</code>.",
"💡 Быстрое добавление сразу многих ключей:":"💡 Adicionar várias chaves de uma vez:",
"На странице Wikimapia вы можете нажать кнопку и создать сразу несколько ключей подряд (например, 5–10 штук).":"Na página da Wikimapia, você pode tocar no botão e criar várias chaves seguidas (por exemplo, de 5 a 10).",
"После этого <b>выделите весь текст страницы</b> (комбинация <b>Ctrl+A</b> на компьютере или долгое нажатие и «Выбрать всё» на смартфоне) и скопируйте его (<b>Ctrl+C</b>).":"Depois, <b>selecione todo o texto da página</b> (<b>Ctrl+A</b> no computador, ou toque longo e \"Selecionar tudo\" no smartphone) e copie-o (<b>Ctrl+C</b>).",
"Затем нажмите в приложении кнопку <b>«📋 Вставить из буфера»</b>. Приложение само найдёт среди скопированного текста все ключи и добавит их по отдельности!":"Em seguida, toque no botão <b>\"📋 Colar da área de transferência\"</b> no aplicativo. O aplicativo encontrará sozinho todas as chaves no texto copiado e as adicionará uma por uma!",
