"🎯 Как это работает":"🎯 Como funciona",
"Выберите на карте 3 чётких ориентира (одиночные деревья на спутниковой карте, перекрёстки троп, углы полян) на удалении 10–50 метров друг от друга. Вы пройдёте по маршруту <b>A → B → C → A</b>. Это настроит точную длину шага под вашу обувь и устранит увод курса. Рекомендуется по возможности повторять каждые 2-3км пути.":"Escolha no mapa 3 pontos de referência nítidos (árvores isoladas no mapa de satélite, cruzamentos de trilhas, cantos de clareiras) a 10–50 metros uns dos outros. Você percorrerá a rota <b>A → B → C → A</b>. Isso ajusta o comprimento exato do passo ao seu calçado e elimina o desvio do rumo. Recomenda-se repetir a cada 2–3 km de percurso, sempre que possível.",
"1. Укажите точки ориентиров:":"1. Indique os pontos de referência:",
"📍 Точка A (Старт)":"📍 Ponto A (Início)",
"📍 Точка B (Второй ориентир)":"📍 Ponto B (Segundo ponto de referência)",
